/* 页脚脚本：子菜单展开收起、侧边栏联动、平滑滚动 */
$(document).ready(function () {
  // 子菜单展开/收起
  $(document).on('click', '.has-sub', function () {
    var e = $(this);
    if ($(this).hasClass('expanded')) {
      $('.has-sub ul').each(function (t, s) {
        var i = $(this);
        if (e.find('ul')[0] == s || expandAll) return;
        setTimeout(function () { i.attr('style', ''); }, 300);
      });
    } else {
      setTimeout(function () { e.find('ul').attr('style', ''); }, 300);
    }
  });

  $('.user-info-menu .hidden-sm').click(function () {
    if ($('.sidebar-menu').hasClass('collapsed')) {
      $('.has-sub.expanded > ul').attr('style', '');
    } else {
      $('.has-sub.expanded > ul').show();
    }
  });

  $('#main-menu li ul li').click(function () {
    $(this).siblings('li').removeClass('active');
    $(this).addClass('active');
  });

  // 平滑滚动到锚点
  $('a.smooth').click(function (e) {
    e.preventDefault();
    public_vars.$mainMenu.add(public_vars.$sidebarProfile).toggleClass('mobile-is-visible');
    ps_destroy();
    $('html, body').animate({ scrollTop: $($(this).attr('href')).offset().top - 30 }, { duration: 500, easing: 'swing' });
    return false;
  });

  // 平滑滚动时同步高亮菜单
  var href = '', pos = 0;
  $('a.smooth').click(function (e) {
    $('#main-menu li').each(function () { $(this).removeClass('active'); });
    $(this).parent('li').addClass('active');
    e.preventDefault();
    href = $(this).attr('href');
    pos = $(href).position().top - 30;
  });
});
